from math import inf


def leaves(node):
    return 1 if isinstance(node, int) else sum(leaves(k) for k in node[2])


def fmt(x):
    return '-inf' if x == -inf else 'inf' if x == inf else str(x)


tree = ('A', 'max', [('B', 'min', [('E', 'max', [3, 15]), ('F', 'max', [16, 1, 19])]),
                     ('C', 'min', [('G', 'max', [8, 18]), ('H', 'max', [20, 6])]),
                     ('D', 'min', [('I', 'max', [11, 17]), ('J', 'max', [21, 9, 14])])])
rows = []


def ab(node, alpha, beta):
    if isinstance(node, int):
        return node
    name, kind, kids = node
    row = [name, fmt(alpha), fmt(beta), None, '0']
    rows.append(row)
    best = -inf if kind == 'max' else inf
    for i, kid in enumerate(kids):
        v = ab(kid, alpha, beta)
        if kind == 'max':
            best = max(best, v)
            if best >= beta:
                row[4] = str(sum(leaves(x) for x in kids[i + 1:]))
                break
            alpha = max(alpha, best)
        else:
            best = min(best, v)
            if best <= alpha:
                row[4] = str(sum(leaves(x) for x in kids[i + 1:]))
                break
            beta = min(beta, best)
    row[3] = str(best)
    return best


def minimax(node):
    if isinstance(node, int):
        return node
    vals = [minimax(k) for k in node[2]]
    return max(vals) if node[1] == 'max' else min(vals)


