edges = {'S': [('A', 1), ('B', 4)], 'A': [('B', 1)], 'B': [('G', 5)]}
h = {'S': 0, 'A': 4, 'B': 0, 'G': 0}


def astar(reopen):
    frontier = {'S': 0}
    closed = {}
    while frontier:
        n = min(frontier, key=lambda x: (frontier[x] + h[x], x))
        g = frontier.pop(n)
        if n == 'G':
            return g
        closed[n] = g
        for m, c in edges.get(n, []):
            if m in closed and not (reopen and g + c < closed[m]):
                continue
            if m in closed:
                del closed[m]
            if m not in frontier or g + c < frontier[m]:
                frontier[m] = g + c


