from itertools import product

pR, pS = 0.3, 0.4
pW = {(1, 1): 0.95, (1, 0): 0.8, (0, 1): 0.7, (0, 0): 0.05}
pL = {1: 0.9, 0: 0.1}


def joint(r, s, w, l):
    p = (pR if r else 1 - pR) * (pS if s else 1 - pS)
    p *= pW[(r, s)] if w else 1 - pW[(r, s)]
    return p * (pL[w] if l else 1 - pL[w])


def prob(**fixed):
    total = 0.0
    for r, s, w, l in product((0, 1), repeat=4):
        values = {'r': r, 's': s, 'w': w, 'l': l}
        if all(values[k] == v for k, v in fixed.items()):
            total += joint(r, s, w, l)
    return total


def independent(a, b, given=None):
    given = given or {}
    pg = prob(**given)
    return abs(prob(**{a: 1, b: 1}, **given) / pg - prob(**{a: 1}, **given) / pg * prob(**{b: 1}, **given) / pg) < 1e-9


