from math import exp


def sig(z):
    return 1 / (1 + exp(-z))


data = [((1.0, 0.0), 1.0), ((0.0, 1.0), 0.0), ((1.0, 1.0), 1.0)]
W = [[0.5, 0.5] for _ in range(3)]
B = [0.0] * 3
V = [0.5] * 3
c = 0.0


def run(x):
    h = [sig(W[j][0] * x[0] + W[j][1] * x[1] + B[j]) for j in range(3)]
    return h, sig(sum(V[j] * h[j] for j in range(3)) + c)


def loss():
    return sum((run(x)[1] - t) ** 2 for x, t in data)


start = loss()
for _ in range(500):
    for x, t in data:
        h, a = run(x)
        do = (a - t) * a * (1 - a)
        dh = [h[j] * (1 - h[j]) * V[j] * do for j in range(3)]
        for j in range(3):
            V[j] -= 0.5 * do * h[j]
            W[j][0] -= 0.5 * dh[j] * x[0]
            W[j][1] -= 0.5 * dh[j] * x[1]
            B[j] -= 0.5 * dh[j]
        c -= 0.5 * do
print('hidden units still identical:', all(abs(W[j][k] - W[0][k]) < 1e-12 for j in range(3) for k in range(2)))
print('loss fell:', loss() < start)

